6:  test("grades editable", { tag: '@functionality' }, async ({ browser }) => {
10:    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
11:    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
12:    expect(await ui.addGrade(pg_uma, "D")).toBe(true);
13:    expect(await ui.addGrade(pg_uma, "D")).toBe(false);
17:    expect(await ui.addGrade(pg_uma, " XY ")).toBe(true);
18:    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "D"}));
19:    expect(await ui.setRate(pg_uma, {"grade": "D", "pct": "40.00"})).toBe(true);
22:    expect(await ui.editPerson(pg_uma, p_ada, {"grade": "XY"})).toBe(true);
26:    await expect(pg_uma.getByTestId("person-row-" + p_ada).getByTestId("person-name")).toHaveText("Ada (XY)");
