import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';

/** A grade of the sheet: its code (A, B or C) and whether it is retired. A retired grade cannot be chosen for a new
 *  person nor in an edit; people already on it keep it. */
export type Grade = { grade: string; retired: boolean };

export const gradesKey = (sheetId: string) => ['sheet', sheetId, 'grades'];

/** The sheet's grades, A, B then C. */
export function useGrades(sheetId: string) {
  return useQuery({
    queryKey: gradesKey(sheetId),
    queryFn: () => getJson<Grade[]>(`/api/sheets/${encodeURIComponent(sheetId)}/grades`),
  });
}
import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { GRADES } from '../people/people';
import { gradesKey, useGrades, type Grade } from './grades';

/** The sheet's grades: the select and button that retire one, the selects and button a steward merges one into another
 *  with, and each grade with whether it is retired. A grade already retired is refused; so is a merge of a grade into
 *  itself, or by anyone but a steward. A merge gives everyone on the merged grade today the other, each as the person
 *  form would, and shows how many it changed; the count is cleared while a new press runs. */
function Grades({ sheetId, user }: { sheetId: string; user: string }) {
  // keyed by sheet, so a count or error shown for one sheet is gone once another is loaded
  return <SheetGrades key={sheetId} sheetId={sheetId} user={user} />;
}

function SheetGrades({ sheetId, user }: { sheetId: string; user: string }) {
  const grades = useGrades(sheetId);
  const queryClient = useQueryClient();
  const [grade, setGrade] = useState<string>(GRADES[0]);
  const [mergeFrom, setMergeFrom] = useState<string>(GRADES[0]);
  const [mergeInto, setMergeInto] = useState<string>(GRADES[1]);

  const submit = useSubmitOnce();
  const retire = useMutation({
    mutationFn: (g: string) =>
      postJson<Grade[]>(`/api/sheets/${encodeURIComponent(sheetId)}/grades/retire`, { grade: g, by: user }),
    onSuccess: (data) => {
      queryClient.setQueryData(gradesKey(sheetId), data);
    },
    onSettled: submit.end,
  });
  const merge = useMutation({
    mutationFn: () =>
      postJson<{ merged: number }>(`/api/sheets/${encodeURIComponent(sheetId)}/grades/merge`, {
        from: mergeFrom,
        into: mergeInto,
        by: user,
      }),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
    onSettled: submit.end,
  });
  const resetAll = () => {
    retire.reset();
    merge.reset();
  };

  return (
    <section data-testid="grades">
      <h3>Grades</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          resetAll();
          retire.mutate(grade);
        }}
      >
        <select
          data-testid="grade-retire-select"
          value={grade}
          onChange={(e) => {
            setGrade(e.target.value);
            resetAll();
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>{' '}
        <button type="submit" data-testid="grade-retire" disabled={retire.isPending}>
          Retire grade
        </button>
      </form>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          resetAll();
          merge.mutate();
        }}
      >
        Merge{' '}
        <select
          data-testid="grade-merge-from"
          value={mergeFrom}
          onChange={(e) => {
            setMergeFrom(e.target.value);
            resetAll();
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>{' '}
        into{' '}
        <select
          data-testid="grade-merge-into"
          value={mergeInto}
          onChange={(e) => {
            setMergeInto(e.target.value);
            resetAll();
          }}
        >
          {GRADES.map((g) => (
            <option key={g} value={g}>
              {g}
            </option>
          ))}
        </select>{' '}
        <button type="submit" data-testid="grade-merge" disabled={merge.isPending}>
          Merge grade
        </button>
        {merge.isSuccess && (
          <>
            {' '}
            Changed <span data-testid="grade-merged">{merge.data.merged}</span>
          </>
        )}
      </form>
      {retire.isError && <p data-testid="grade-error">The grade is already retired.</p>}
      {merge.isError && <p data-testid="grade-error">The grade could not be merged.</p>}
      {grades.isError && <p data-testid="grades-load-error">Could not load grades.</p>}
      <table>
        <tbody>
          {(grades.data ?? []).map((g) => (
            <tr key={g.grade} data-testid={`grade-row-${g.grade}`}>
              <td>{g.grade}</td>
              <td>
                Retired <span data-testid="grade-retired">{g.retired ? 'yes' : 'no'}</span>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 5.5, Component: Grades });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { nowKey, useReadNow } from '../../query/readNow';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade a person has from a date (yyyy-MM-dd) until their next one's; a null `from` applies from the beginning of
 *  time (the first grade the person was given). */
export type PersonGrade = { grade: string; from: string | null };

/** A person on the sheet. `name` is unique on the sheet (case ignored), kept without outer spaces; `grades` are the
 *  grades recorded, by from-date, and `grade` (A, B or C) the one in force on the sheet's today.
 *  `version` goes up by one on each stored edit; an edit sends the version it was made from. `retiredFrom` (yyyy-MM-dd)
 *  is the date the person is retired from, null when not retired: a person with one counts as retired at once. `holds` are
 *  the person's holds, by from-date: a claim of theirs dated within one still counts in every total; a hold
 *  only takes the person's cut in the pools. `held` is whether they have any hold. `terms` are the person's own terms in days (ahead of
 *  their grade's and the sheet's when a claim is added) in force on the sheet's today, null when they have none;
 *  `ownTerms` are their own terms as recorded, by from-date (null: from the beginning of time), a claim having those in
 *  force on its date. `contact` is the person's contact
 *  (unique on the sheet; without surrounding spaces, lower-cased), null when none. `aliases` are the person's aliases,
 *  sorted as names are compared: no alias equals (case ignored) any name or alias on the sheet, and the quick-add bar and
 *  the paste box find a person by one as by the name. `clashing` is whether their name or an alias is used as a name or
 *  alias on another sheet of the sheet's tree (people added before the rule): every edit of them is refused until it
 *  renames them clear. `origin` is the sheet they were last transferred from, null when never transferred here.
 *  `retirements` are their past retirements (each ended by unretiring them), in the order they ended.
 *  `tags` are the person's tags (each trimmed and in lower case, no repeats, sorted; empty when none): a claim of theirs
 *  counts for each in the tag totals. */
/** A person's own terms in days (null: none) from a date (yyyy-MM-dd; null: the beginning of time). */
export type PersonTerms = { days: number | null; from: string | null };

export type Person = {
  id: number;
  sheetId: string;
  name: string;
  grade: string;
  version: number;
  retiredFrom: string | null;
  held: boolean;
  grades: PersonGrade[];
  holds: PersonHold[];
  terms: number | null;
  ownTerms: PersonTerms[];
  contact: string | null;
  aliases: string[];
  clashing: boolean;
  origin: string | null;
  retirements: PersonRetirement[];
  tags: string[];
  flag: PersonFlag | null;
};

/** A steward's flag on a person: its reason, in force until its until-date (yyyy-MM-dd, included). While the sheet's
 *  today is on or before it only a steward may open a claim of the person; after it the flag shows nothing. */
export type PersonFlag = { reason: string; until: string };

/** The reason of the person's flag in force on the day (yyyy-MM-dd), or '' when none is. */
export const flagOn = (person: Pick<Person, 'flag'>, on: string) =>
  person.flag && on !== '' && on <= person.flag.until ? person.flag.reason : '';

